mapper.select:
SELECT r.id, r.room_number, r.room_type_id, rt.type_name as roomTypeName,
r.floor, r.status, r.create_time
FROM room r
LEFT JOIN room_type rt ON r.room_type_id = rt.id


        AND r.room_number LIKE CONCAT('%', #{roomNumber}, '%')


        AND r.room_type_id = #{roomTypeId}


        AND r.floor = #{floor}


        AND r.status = #{status}


ORDER BY r.update_time DESC

SELECT r.id, r.room_number as roomNumber, r.room_type_id as roomTypeId,
rt.type_name as roomTypeName, r.floor, r.status
FROM room r
LEFT JOIN room_type rt ON r.room_type_id = rt.id


        AND r.floor = #{floor}


        AND r.status = #{status}


        AND r.room_type_id = #{roomTypeId}


ORDER BY r.room_number ASC
